import{_ as e,o as a,c as r,a0 as n}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"🛠️ The WealthFam Tech Stack","description":"","frontmatter":{},"headers":[],"relativePath":"technical/stack.md","filePath":"technical/stack.md"}'),s={name:"technical/stack.md"};function i(l,t,o,d,c,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="🛠️-the-wealthfam-tech-stack" tabindex="-1">🛠️ The WealthFam Tech Stack <a class="header-anchor" href="#🛠️-the-wealthfam-tech-stack" aria-label="Permalink to &quot;🛠️ The WealthFam Tech Stack&quot;">​</a></h1><p>WealthFam is built on a &quot;Local-First, AI-Augmented&quot; philosophy. Every technology in our stack is chosen for its performance, privacy characteristics, and developer experience.</p><hr><h2 id="🚀-backend-fastapi-python-3-10" tabindex="-1">🚀 Backend: FastAPI &amp; Python 3.10+ <a class="header-anchor" href="#🚀-backend-fastapi-python-3-10" aria-label="Permalink to &quot;🚀 Backend: FastAPI &amp; Python 3.10+&quot;">​</a></h2><p>We chose <strong>FastAPI</strong> as the central orchestrator for its modern features:</p><ul><li><strong>High Performance</strong>: Built on Starlette and Pydantic, it is one of the fastest Python frameworks available.</li><li><strong>Type Safety</strong>: Leveraging Python type hints for automatic validation and interactive API documentation (Swagger/OpenAPI).</li><li><strong>Asynchronous Support</strong>: Perfect for handling multiple concurrent ingestion streams (SMS, Email, Web).</li></ul><hr><h2 id="🗄️-database-stack-postgresql-duckdb" tabindex="-1">🗄️ Database Stack: PostgreSQL &amp; DuckDB <a class="header-anchor" href="#🗄️-database-stack-postgresql-duckdb" aria-label="Permalink to &quot;🗄️ Database Stack: PostgreSQL &amp; DuckDB&quot;">​</a></h2><p>WealthFam utilizes a dual-database approach designed for both transactional robustness and telemetry timeseries:</p><ul><li><strong>PostgreSQL (Core Backend DB)</strong>: Used as the primary relational database. This provides robust multi-user transactional integrity, concurrency support, indexing, and standard schema migrations using Alembic (plus Document Vault metadata, cross-source deduplication indices, and <code>brand_logos</code>).</li><li><strong>DuckDB (Admin Telemetry Timeseries &amp; Control Plane)</strong>: Embedded timeseries database managed by <code>Admin-Backend</code> (<code>data/telemetry.duckdb</code>) for anonymous API latency metrics, parser events, client crash events, scrubbed system logs, active 30s endpoint probes, and declarative parser templates.</li><li><strong>Stateless Financial Parser</strong>: The Parser microservice is <strong>100% stateless and code-driven</strong>. It performs zero disk writes, persists zero customer PII, and handles idempotency through an in-memory thread-safe 5-minute sliding LRU cache (<code>RecentSubmissionCache</code>).</li></ul><hr><h2 id="🎨-frontend-vue-3-material-3" tabindex="-1">🎨 Frontend: Vue 3 &amp; Material 3 <a class="header-anchor" href="#🎨-frontend-vue-3-material-3" aria-label="Permalink to &quot;🎨 Frontend: Vue 3 &amp; Material 3&quot;">​</a></h2><p>Our web interface is designed for clarity and responsiveness:</p><ul><li><strong>Vue 3 (Composition API)</strong>: Provides a clean, reactive architecture for complex financial dashboards.</li><li><strong>Vite</strong>: The next-generation frontend tool that ensures near-instant development starts and builds.</li><li><strong>Material Design 3 (M3)</strong>: We strictly follow M3 principles to ensure the UI is accessible, beautiful, and feels native on every device.</li><li><strong>Tailwind CSS</strong>: For high-fidelity, utility-first styling that doesn&#39;t bloat the bundle.</li></ul><hr><h2 id="📱-mobile-flutter" tabindex="-1">📱 Mobile: Flutter <a class="header-anchor" href="#📱-mobile-flutter" aria-label="Permalink to &quot;📱 Mobile: Flutter&quot;">​</a></h2><p>The <strong>WealthFam Mobile</strong> app (Android) is built with <strong>Flutter</strong>:</p><ul><li><strong>Native Performance</strong>: Compiles to ARM machine code for smooth 60fps animations.</li><li><strong>Native Integration</strong>: Essential for our background SMS listeners and device hashing capabilities.</li><li><strong>Single Codebase</strong>: Allows us to maintain a consistent experience if we expand to iOS in the future.</li></ul><hr><h2 id="⚡-deterministic-engine-native-python-parsers" tabindex="-1">⚡ Deterministic Engine: Native Python Parsers <a class="header-anchor" href="#⚡-deterministic-engine-native-python-parsers" aria-label="Permalink to &quot;⚡ Deterministic Engine: Native Python Parsers&quot;">​</a></h2><p>Rather than relying on expensive, nondeterministic cloud LLMs that risk privacy exposure:</p><ul><li><strong>Deterministic Accuracy</strong>: 23+ Indian bank parser classes and 100+ compiled regexes provide &gt;95% confidence on financial alerts.</li><li><strong>Sub-Millisecond Speed</strong>: In-memory parsing finishes in &lt; 0.5ms with zero network hops.</li><li><strong>Complete Privacy</strong>: Customer transaction text never leaves the local environment.</li></ul><hr><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Technology</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Orchestration</strong></td><td style="text-align:left;"><a href="https://fastapi.tiangolo.com/" target="_blank" rel="noreferrer">FastAPI</a></td><td style="text-align:left;">API Gateways &amp; Business Logic</td></tr><tr><td style="text-align:left;"><strong>Persistence (Backend)</strong></td><td style="text-align:left;"><a href="https://www.postgresql.org/" target="_blank" rel="noreferrer">PostgreSQL</a></td><td style="text-align:left;">Relational Ledger, ACID Concurrency &amp; Document Vault</td></tr><tr><td style="text-align:left;"><strong>Telemetry (Admin)</strong></td><td style="text-align:left;"><a href="https://duckdb.org/" target="_blank" rel="noreferrer">DuckDB</a></td><td style="text-align:left;">Anonymous Telemetry Timeseries &amp; Scrubbed Logs (<code>telemetry.duckdb</code>)</td></tr><tr><td style="text-align:left;"><strong>Admin Control Plane</strong></td><td style="text-align:left;">FastAPI + Vue 3</td><td style="text-align:left;"><code>Admin-Backend</code> (<code>:8002</code>) &amp; <code>Admin-Web</code> (<code>:8080</code> / <code>:5174</code>)</td></tr><tr><td style="text-align:left;"><strong>Parsing Engine</strong></td><td style="text-align:left;">Stateless Python 3.10+</td><td style="text-align:left;">Compiled Bank Regex Registry &amp; In-Memory LRU Cache</td></tr><tr><td style="text-align:left;"><strong>Interface</strong></td><td style="text-align:left;"><a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js 3</a></td><td style="text-align:left;">Web Dashboard</td></tr><tr><td style="text-align:left;"><strong>Mobile</strong></td><td style="text-align:left;"><a href="https://flutter.dev/" target="_blank" rel="noreferrer">Flutter</a></td><td style="text-align:left;">Real-time SMS Ingestion</td></tr><tr><td style="text-align:left;"><strong>Extraction Libraries</strong></td><td style="text-align:left;"><code>pdfplumber</code>, <code>casparser</code></td><td style="text-align:left;">Bank Statements &amp; Mutual Fund CAS Extraction</td></tr><tr><td style="text-align:left;"><strong>Styling</strong></td><td style="text-align:left;"><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a></td><td style="text-align:left;">Material 3 Implementation</td></tr></tbody></table><hr><div align="center"> *Engineering Excellence · Local Isolation · Precision Accuracy* </div>',26)])])}const u=e(s,[["render",i]]);export{m as __pageData,u as default};
